    "lists_arrays",
    "' Lists and arrays count from 0; ReDim Preserve keeps values.\nSub Main()\n    Dim names As New List(Of String)\n    names.Add(\"Kim\")\n    names.Add(\"Lee\")\n    names.Insert(0, \"Park\")\n    Debug.Print(names.Count & \" \" & names(0) & \" \" & names(2))\n    Debug.Print(names.Contains(\"Lee\") & \" \" & names.IndexOf(\"Kim\") & \" \" & names.IndexOf(\"X\"))\n    names.Remove(\"Kim\")\n    names.RemoveAt(0)\n    Debug.Print(names.Count & \" \" & names(0))\n    Dim a(3) As Integer\n    For i = 0 To UBound(a)\n        a(i) = i * i\n    Next\n    ReDim Preserve a(5)\n    Debug.Print(a(3) & \" \" & a(5) & \" \" & a.Length)\n    Try\n        Debug.Print(a(6))\n    Catch ex As Exception\n        Debug.Print(\"Out of range\")\n    End Try\n    names(0) = \"Choi\"\n    Debug.Print(names(0))\nEnd Sub\n",
